75	export function appendSyncHistory(ledger: Ledger): void {
76	  const history = readSyncHistory();
77	
78	  const bySource: Record<string, number> = {};
79	  for (const s of ledger.rawSignals) {
80	    bySource[s.source] = (bySource[s.source] ?? 0) + 1;
81	  }
82	
83	  const byCategory: Record<string, number> = {};
84	  for (const c of ledger.candidates) {
85	    const cat = c.candidateType ?? "unknown";
86	    byCategory[cat] = (byCategory[cat] ?? 0) + 1;
87	  }
88	
89	  const obligationItems = ledger.obligations.map((o) => ({
90	    id: o.id,
91	    description: o.description ?? "",
92	    status: o.status,
93	    policyRef: o.rule,
94	  }));
95	
96	  const run: SyncHistoryRun = {
97	    id: randomUUID(),
98	    timestamp: new Date().toISOString(),
