382	// ============================================================================
383	// Rotate: keep last N signals, discard rest (controlled context size)
384	// ===========================================================================
385	
386	export interface RotateOpts {
387	  commitHash?: string;
388	  branch?: string;
389	  topic?: string;
390	  /** Max raw signals to keep (default 50) */
391	  maxSignals?: number;
392	}
393	
394	export function rotateLedger(prev: Ledger, opts: RotateOpts): Ledger {
395	  const maxSignals = opts.maxSignals ?? 50;
396	  const now = new Date().toISOString();
397	
398	  // Keep only the most recent N signals
399	  const sortedSignals = [...prev.rawSignals]
400	    .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
401	    .slice(0, maxSignals);
402	
403	  // Retain candidates linked to surviving signals
404	  const signalIds = new Set(sortedSignals.map((s) => s.id));
405	  const retainedCandidates = prev.candidates.filter(
406	    (c) => c.signalIds.some((id) => signalIds.has(id))
407	  );
408	
409	  // Retain transition notes linked to surviving candidates/obligations
410	  const candidateIds = new Set(retainedCandidates.map((c) => c.id));
411	  const retainedNotes = prev.transitionNotes.filter(
412	    (n) =>
413	      (n.relatedCandidateId && candidateIds.has(n.relatedCandidateId)) ||
414	      (n.relatedObligationId && prev.obligations.some((o) => o.id === n.relatedObligationId))
415	  );
416	
417	  return {
418	    ...prev,
419	    version: 2,
420	    sessionMeta: {
421	      ...prev.sessionMeta,
422	      updatedAt: now,
423	      topic: opts.topic ?? prev.sessionMeta.topic,
424	    },
425	    rawSignals: sortedSignals,
426	    candidates: retainedCandidates,
427	    // Obligations are cleared — they are re-derived each sync via mergeWithPreviousLedger
428	    obligations: [],
429	    transitionNotes: retainedNotes,
430	    syncRunState: {
431	      currentPhase: "raw",
432	      rawSignalIds: sortedSignals.map((s) => s.id),
433	      candidateIds: retainedCandidates.map((c) => c.id),
434	      obligationIds: [],
435	      syncStatus: "draft",
436	    },
437	    completionStatus: prev.completionStatus,
438	    commitHash: opts.commitHash ?? prev.commitHash,
439	    branch: opts.branch ?? prev.branch,
440	    updatedAt: now,
441	  };
442	}
