445	// Add a RawSignal to the ledger
446	// ============================================================================
447	
448	export function addSignal(
449	  ledger: Ledger,
450	  signal: Omit<RawSignal, "id" | "createdAt" | "status">
451	): RawSignal {
452	  const entry: RawSignal = {
453	    id: randomUUID(),
454	    createdAt: new Date().toISOString(),
455	    status: "new",
456	    ...signal,
457	  };
458	  ledger.rawSignals.push(entry);
459	  ledger.syncRunState.rawSignalIds.push(entry.id);
460	  ledger.sessionMeta.updatedAt = entry.createdAt;
461	  return entry;
462	}
