481	// ============================================================================
482	// Completion status derivation
483	// ============================================================================
484	
485	export function deriveCompletionStatus(obligations: ObligationEntry[]): CompletionStatus {
486	  const open = obligations.filter((o) => o.status === "open");
487	  const criticalOpen = open.filter((o) => o.priority === "critical");
488	  const importantOpen = open.filter((o) => o.priority === "important");
489	
490	  if (criticalOpen.length > 0) return "blocked";
491	  if (importantOpen.length > 0) return "incomplete";
492	  return "complete";
493	}
