495	// ============================================================================
496	// Merge: preserve deferrals and resolutions from previous ledger
497	// ============================================================================
498	
499	export function mergeWithPreviousLedger(
500	  newObligations: Omit<ObligationEntry, "status" | "detectedAt" | "resolvedAt" | "deferralReason" | "deferReviewAt">[],
501	  previous: Ledger | null
502	): ObligationEntry[] {
503	  const now = new Date().toISOString();
504	
505	  return newObligations.map((o) => {
506	    const prev = previous?.obligations.find(
507	      (p) => p.rule === o.rule && p.artifactId === o.artifactId
508	    );
509	
510	    if (prev && (prev.status === "deferred" || prev.status === "waived" || prev.status === "resolved")) {
511	      return {
512	        ...o,
513	        status: prev.status,
514	        detectedAt: prev.detectedAt,
515	        resolvedAt: prev.resolvedAt,
516	        deferralReason: prev.deferralReason,
517	        deferReviewAt: prev.deferReviewAt,
518	      };
519	    }
520	
521	    return {
522	      ...o,
523	      status: "open" as ObligationStatus,
524	      detectedAt: now,
525	    };
526	  });
527	}
