9	// ============================================================================
10	// Collect all signals from the three sources
11	// ============================================================================
12	
13	export interface SignalCollectionResult {
14	  fromLedger: RawSignal[];
15	  fromArtifacts: RawSignal[];
16	  fromCode: RawSignal[];
17	  all: RawSignal[];
18	}
19	
20	/**
21	 * Collect RawSignals from all three sources into the ledger.
22	 * Returns the collected signals grouped by source.
23	 */
24	export function collectSignals(
25	  ledger: Ledger,
26	  ctx: SyncContext,
27	  since: Date
28	): SignalCollectionResult {
29	  // 1. Existing ledger signals (conversation + manual) — already present
30	  const fromLedger = ledger.rawSignals.filter(
31	    (s) => s.status === "new" && (s.source === "conversation" || s.source === "manual")
32	  );
33	
34	  // 2. Artifact observations from pre-fetched context
35	  const fromArtifacts = collectArtifactSignals(ledger, ctx, since);
36	
37	  // 3. Code observations from git diff
38	  const fromCode = collectCodeSignals(ledger, since);
39	
40	  return {
41	    fromLedger,
42	    fromArtifacts,
43	    fromCode,
44	    all: [...fromLedger, ...fromArtifacts, ...fromCode],
45	  };
46	}
