48	// ============================================================================
49	// Signal deduplication
50	// ============================================================================
51	
52	/**
53	 * Checks if a signal with the same source and primary evidence ref
54	 * already exists in the ledger (not discarded).
55	 */
56	function signalExists(ledger: Ledger, source: string, evidenceRef: string): boolean {
57	  return ledger.rawSignals.some(
58	    (s) => s.source === source &&
59	           s.status !== "discarded" &&
60	           s.evidenceRefs?.includes(evidenceRef)
61	  );
62	}
