64	// ============================================================================
65	// Artifact observation signals (from SyncContext)
66	// ============================================================================
67	
68	function collectArtifactSignals(
69	  ledger: Ledger,
70	  ctx: SyncContext,
71	  since: Date
72	): RawSignal[] {
73	  const signals: RawSignal[] = [];
74	
75	  // --- Decisions ---
76	  for (const d of ctx.decisions) {
77	    const created = d.createdAt ?? d.created_at;
78	    const updated = d.updatedAt ?? d.updated_at;
79	    const isNew = created && new Date(created) > since;
80	    const isChanged = updated && new Date(updated) > since && !isNew;
81	
82	    if (isNew) {
83	      const ref = `decision:${d.id}`;
84	      if (signalExists(ledger, "artifact_observation", ref)) continue;
85	
86	      const durability = d.durability ?? "unbekannt";
87	      const tradeOff = d.tradeOffId ?? d.trade_off_id;
88	      const modelRefs = d.modelRefs ?? d.model_refs ?? [];
89	      const details = [
90	        `durability=${durability}`,
91	        tradeOff ? `trade-off=${tradeOff}` : "kein Trade-off",
92	        modelRefs.length > 0 ? `model-refs=${modelRefs.length}` : "keine Modell-Referenz",
93	      ].join(", ");
94	
95	      signals.push(addSignal(ledger, {
96	        source: "artifact_observation",
97	        summary: `Neue Entscheidung: „${d.title}" (${details})`,
98	        evidenceRefs: [ref],
99	      }));
100	    } else if (isChanged) {
101	      const ref = `decision:${d.id}`;
102	      if (signalExists(ledger, "artifact_observation", ref)) continue;
103	
104	      signals.push(addSignal(ledger, {
105	        source: "artifact_observation",
106	        summary: `Geänderte Entscheidung: „${d.title}"`,
107	        evidenceRefs: [ref],
108	      }));
109	    }
110	  }
111	
112	  // --- Preferences (only active) ---
113	  const activePrefs = ctx.preferences.filter((p) => p.status === "active");
114	  for (const p of activePrefs) {
115	    const ref = `preference:${p.id}`;
116	    if (signalExists(ledger, "artifact_observation", ref)) continue;
117	
118	    signals.push(addSignal(ledger, {
119	      source: "artifact_observation",
120	      summary: `Aktive Präferenz: „${p.title}" (${p.source ?? "unbekannt"})`,
121	      evidenceRefs: [ref],
122	    }));
123	  }
124	
125	  // --- Tasks without feature reference ---
126	  const orphanTasks = ctx.tasks.filter((t) => !(t.featureId ?? t.feature_id));
127	  for (const t of orphanTasks) {
128	    const ref = `task:${t.id}`;
129	    if (signalExists(ledger, "artifact_observation", ref)) continue;
130	
131	    signals.push(addSignal(ledger, {
132	      source: "artifact_observation",
133	      summary: `Entwicklungsaufgabe ohne Feature-Referenz: „${t.title}"`,
134	      evidenceRefs: [ref],
135	    }));
136	  }
137	
138	  // --- Milestones without feature bundling ---
139	  for (const m of ctx.milestones) {
140	    const linkedFeatures = m.milestoneFeatures ?? m.milestone_features ?? [];
141	    if (linkedFeatures.length === 0 && m.status !== "completed" && m.status !== "cancelled") {
142	      const ref = `milestone:${m.id}`;
143	      if (signalExists(ledger, "artifact_observation", ref)) continue;
144	
145	      signals.push(addSignal(ledger, {
146	        source: "artifact_observation",
147	        summary: `Meilenstein ohne Feature-Bündelung: „${m.name}"`,
148	        evidenceRefs: [ref],
149	      }));
150	    }
151	  }
152	
153	  return signals;
154	}
