156	// ============================================================================
157	// Code observation signals (from git diff)
158	// ============================================================================
159	
160	function collectCodeSignals(
161	  ledger: Ledger,
162	  _since: Date
163	): RawSignal[] {
164	  const signals: RawSignal[] = [];
165	
166	  try {
167	    const diffOutput = execSync(
168	      "git diff --cached --name-only 2>/dev/null || git diff --name-only HEAD",
169	      { encoding: "utf-8" }
170	    ).trim();
171	
172	    if (!diffOutput) return signals;
173	
174	    const files = diffOutput.split("\n").filter(Boolean);
175	
176	    // Model/policy changes
177	    const modelFiles = files.filter((f) =>
178	      f.includes("docs/konzept") || f.includes("orcha-model")
179	    );
180	    for (const f of modelFiles) {
181	      const ref = `file:${f}`;
182	      if (signalExists(ledger, "code_observation", ref)) continue;
183	
184	      signals.push(addSignal(ledger, {
185	        source: "code_observation",
186	        summary: `Modell-/Policy-Datei geändert: ${f}`,
187	        evidenceRefs: [ref],
188	      }));
189	    }
190	
191	    // Flow/intent changes
192	    const flowFiles = files.filter((f) =>
193	      f.includes("userflow") || f.includes("absicht") || f.includes("flow")
194	    );
195	    for (const f of flowFiles) {
196	      const ref = `file:${f}`;
197	      if (signalExists(ledger, "code_observation", ref)) continue;
198	
199	      signals.push(addSignal(ledger, {
200	        source: "code_observation",
201	        summary: `Flow-Datei geändert: ${f}`,
202	        evidenceRefs: [ref],
203	      }));
204	    }
205	
206	    // Skill changes
207	    const skillFiles = files.filter((f) =>
208	      f.includes("skill") && !f.includes("node_modules")
209	    );
210	    for (const f of skillFiles) {
211	      const ref = `file:${f}`;
212	      if (signalExists(ledger, "code_observation", ref)) continue;
213	
214	      signals.push(addSignal(ledger, {
215	        source: "code_observation",
216	        summary: `Skill-Datei geändert: ${f}`,
217	        evidenceRefs: [ref],
218	      }));
219	    }
220	  } catch {
221	    // git not available
222	  }
223	
224	  return signals;
225	}
