1	import { randomUUID } from "crypto";
2	import type {
3	  Ledger,
4	  RawSignal,
5	  Candidate,
6	  CandidateType,
7	  ArtifactRef,
8	} from "./ledger.js";
9	
10	// ============================================================================
11	// Classify RawSignals into Candidates
12	// ============================================================================
13	
14	/**
15	 * Takes all unclassified (status: "new") signals from the ledger,
16	 * creates Candidates, and marks signals as "classified".
17	 * Returns the newly created Candidates.
18	 */
19	export function classifyCandidates(ledger: Ledger): Candidate[] {
20	  const newSignals = ledger.rawSignals.filter((s) => s.status === "new");
21	  const candidates: Candidate[] = [];
22	
23	  for (const signal of newSignals) {
24	    const candidateType = inferCandidateType(signal);
25	    const artifactRefs = extractArtifactRefs(signal);
26	
27	    // Check for existing candidate with same artifact ref — merge signals
28	    const existing = candidateType && artifactRefs.length > 0
29	      ? candidates.find(
30	          (c) => c.candidateType === candidateType &&
31	                 c.artifactRefs?.some((r) => artifactRefs.some((a) => a.id === r.id))
32	        )
33	      : null;
34	
35	    if (existing) {
36	      // Merge: add signal to existing candidate
37	      existing.signalIds.push(signal.id);
38	      if (!existing.summary.includes(signal.summary)) {
39	        existing.summary += ` + ${signal.summary}`;
40	      }
41	    } else {
42	      const candidate: Candidate = {
43	        id: randomUUID(),
44	        signalIds: [signal.id],
45	        candidateType: candidateType ?? "episodic",
46	        summary: signal.summary,
47	        artifactRefs: artifactRefs.length > 0 ? artifactRefs : undefined,
48	        phase: "classified",
49	        action: "unresolved",
50	      };
51	      candidates.push(candidate);
52	      ledger.syncRunState.candidateIds.push(candidate.id);
53	    }
54	
55	    // Mark signal as classified
56	    signal.status = "classified";
57	  }
58	
59	  ledger.candidates.push(...candidates);
60	  return candidates;
61	}
62	
63	// ============================================================================
64	// Normalize Candidates — enrich references, merge duplicates
65	// ============================================================================
66	
67	/**
68	 * Normalizes candidates: enriches artifact references,
69	 * detects duplicates from different sources, advances phase.
70	 */
71	export function normalizeCandidates(ledger: Ledger): void {
72	  const unprocessed = ledger.candidates.filter((c) => c.phase === "classified");
73	
74	  for (const candidate of unprocessed) {
75	    // Merge duplicates: if two candidates reference the same artifact with the same type
76	    const duplicate = ledger.candidates.find(
77	      (other) =>
78	        other.id !== candidate.id &&
79	        other.phase === "normalized" &&
80	        other.candidateType === candidate.candidateType &&
81	        other.artifactRefs?.some((r) =>
82	          candidate.artifactRefs?.some((cr) => cr.id === r.id && cr.type === r.type)
83	        )
84	    );
85	
86	    if (duplicate) {
87	      // Merge into existing normalized candidate
88	      duplicate.signalIds.push(...candidate.signalIds);
89	      // Remove the duplicate from the ledger
90	      const idx = ledger.candidates.indexOf(candidate);
91	      if (idx >= 0) ledger.candidates.splice(idx, 1);
92	      continue;
93	    }
94	
95	    candidate.phase = "normalized";
96	  }
97	}
98	
99	// ============================================================================
100	// Type inference from signal content
101	// ============================================================================
102	
103	const TYPE_PATTERNS: [RegExp, CandidateType][] = [
104	  // German patterns (primary)
105	  [/entscheidung|decision|beschluss/i, "decision"],
106	  [/präferenz|wunsch|vorliebe|bevorzug/i, "preference"],
107	  [/constraint|einschränkung|beschränkung/i, "constraint"],
108	  [/trade-off|abwägung|spannungsfeld/i, "tradeoff"],
109	  [/annahme|assumption|hypothese/i, "assumption"],
110	  [/befund|gap|widerspruch|problem|lücke/i, "finding"],
111	  [/aufgabe(?! ohne)|task(?! ohne)/i, "task"],
112	  [/meilenstein|milestone/i, "milestone_candidate"],
113	  [/flow|ablauf|userflow|absicht/i, "flow_change"],
114	  // P-F10: Weiterentwicklung eines bestehenden Features → Iteration, nicht Subfeature.
115	  // Muss vor feature_change stehen, da Weiterentwicklung einen Feature-Kontext impliziert.
116	  [/weiterentwicklung|überarbeitung|neuauflage|neue iteration|nächste iteration|iteration \d|v\d+ (?:der|von)|v2|v3|v4|v5/i, "feature_iterate"],
117	  [/feature|fähigkeit/i, "feature_change"],
118	  [/semantisch|konsolidier/i, "recommend_semantic"],
119	  [/prozedural|workflow|pattern/i, "recommend_procedural"],
120	
121	  // Conversation-signal patterns (Konzept-Erkenntnisse, Designprinzipien, etc.)
122	  [/konzept-?erkenntnis|erkenntnis:|insight:/i, "finding"],
123	  [/designprinzip|design-prinzip|prinzip:/i, "preference"],
124	  [/lücke|fehlende? |nicht vorhanden|nicht definiert|fehlt/i, "finding"],
125	  [/erweiterung|handoff|übergabe|erweitert/i, "task"],
126	  [/idee:|feature-idee|verbesserung|vorschlag/i, "task"],
127	  [/modell|konzept-?erweiterung|konzept:|rahmen/i, "assumption"],
128	
129	  // Artifact observation patterns
130	  [/neue entscheidung:|geänderte entscheidung:/i, "decision"],
131	  [/aktive präferenz:/i, "preference"],
132	  [/entwicklungsaufgabe ohne feature/i, "task"],
133	  [/meilenstein ohne feature/i, "milestone_candidate"],
134	  [/modell-.*datei geändert|policy-.*datei geändert/i, "episodic"],
135	  [/skill-datei geändert/i, "episodic"],
136	  [/flow-datei geändert/i, "flow_change"],
137	];
138	
139	function inferCandidateType(signal: RawSignal): CandidateType | null {
140	  for (const [pattern, type] of TYPE_PATTERNS) {
141	    if (pattern.test(signal.summary)) return type;
142	  }
143	  return null;
144	}
145	
146	// ============================================================================
147	// Extract artifact refs from signal evidence
148	// ============================================================================
149	
150	function extractArtifactRefs(signal: RawSignal): ArtifactRef[] {
151	  const refs: ArtifactRef[] = [];
152	  if (!signal.evidenceRefs) return refs;
153	
154	  for (const ref of signal.evidenceRefs) {
155	    // Format: "decision:uuid", "task:uuid", "preference:uuid", etc.
156	    const match = ref.match(/^(\w+):(.+)$/);
157	    if (match) {
158	      const [, type, id] = match;
159	      if (type !== "file") { // file refs are not artifact refs
160	        refs.push({ type, id });
161	      }
162	    }
163	  }
164	
165	  return refs;
166	}
