1	import type {
2	  Ledger,
3	  ObligationEntry,
4	  ObligationPriority,
5	  ArtifactRef,
6	} from "./ledger.js";
7	import type { SyncContext } from "./sync-context.js";
8	
9	// ============================================================================
10	// Obligation draft type (before merge with previous ledger)
11	// ============================================================================
12	
13	export type ObligationDraft = Omit<
14	  ObligationEntry,
15	  "status" | "detectedAt" | "resolvedAt" | "deferralReason" | "deferReviewAt"
16	>;
17	
18	// ============================================================================
19	// Derive obligations from candidates + SyncContext enrichment
20	// ============================================================================
21	
22	/**
23	 * Derives obligations from normalized candidates in the ledger.
24	 * Uses pre-fetched SyncContext for enrichment data.
25	 */
26	export function deriveObligationsFromCandidates(
27	  ledger: Ledger,
28	  ctx: SyncContext,
29	  since: Date
30	): ObligationDraft[] {
31	  const obligations: ObligationDraft[] = [];
32	
33	  // Build lookup maps
34	  const decisionById = new Map(ctx.decisions.map((d) => [d.id as string, d]));
35	  const taskById = new Map(ctx.tasks.map((t) => [t.id as string, t]));
36	  const milestoneById = new Map(ctx.milestones.map((m) => [m.id as string, m]));
37	
38	  // Collect P-MS01 hits for aggregation
39	  const ms01Hits: { milestone: Record<string, unknown>; signalRefs: string[]; ref: ArtifactRef }[] = [];
40	
41	  // Process each candidate
42	  for (const candidate of ledger.candidates) {
43	    if (candidate.action === "discard") continue;
44	
45	    const signalRefs = candidate.signalIds;
46	
47	    // --- Decision candidates ---
48	    if (candidate.candidateType === "decision") {
49	      const decisionRef = candidate.artifactRefs?.find((r) => r.type === "decision");
50	      const decision = decisionRef ? decisionById.get(decisionRef.id) : null;
51	
52	      if (decision) {
53	        const durability = decision.durability;
54	        const plannedSuccessor = decision.plannedSuccessor ?? decision.planned_successor;
55	        const reviewCondition = decision.reviewCondition ?? decision.review_condition;
56	        const tradeOffId = decision.tradeOffId ?? decision.trade_off_id;
57	        const modelRefs = decision.modelRefs ?? decision.model_refs ?? [];
58	
59	        // P-E01: Decision ohne Durability (critical)
60	        if (!durability) {
61	          obligations.push(makeObligation({
62	            rule: "P-E01",
63	            artifactId: decision.id,
64	            artifactTitle: decision.title,
65	            signalType: "decision",
66	            priority: "critical",
67	            description: `Entscheidung ohne Dauerhaftigkeit: „${decision.title}"`,
68	            reason: "Jede Entscheidung muss ihre Dauerhaftigkeit (permanent/temporary/transitional) benennen.",
69	            sourceSignalRefs: signalRefs,
70	            relatedArtifactRefs: [{ type: "decision", id: decision.id }],
71	          }));
72	        }
73	
74	        // P-E02: Temp/transitional ohne Nachfolger/Review (important)
75	        if (
76	          (durability === "temporary" || durability === "transitional") &&
77	          !plannedSuccessor && !reviewCondition
78	        ) {
79	          obligations.push(makeObligation({
80	            rule: "P-E02",
81	            artifactId: decision.id,
82	            artifactTitle: decision.title,
83	            signalType: "decision",
84	            priority: "important",
85	            description: `Temporäre Entscheidung ohne Nachfolger oder Review: „${decision.title}"`,
86	            reason: "Temporäre/transitionale Entscheidungen brauchen geplanten Nachfolger oder Review-Bedingung.",
87	            sourceSignalRefs: signalRefs,
88	            relatedArtifactRefs: [{ type: "decision", id: decision.id }],
89	          }));
90	        }
91	
92	        // P-E03: Decision ohne Trade-off (recommended) — nur neue
93	        const created = decision.createdAt ?? decision.created_at;
94	        const isNew = created && new Date(created) > since;
95	        if (isNew && !tradeOffId) {
96	          obligations.push(makeObligation({
97	            rule: "P-E03",
98	            artifactId: decision.id,
99	            artifactTitle: decision.title,
100	            signalType: "decision",
101	            priority: "recommended",
102	            description: `Neue Entscheidung ohne Trade-off-Verknüpfung: „${decision.title}"`,
103	            reason: "Decisions sollten auf den Trade-off verweisen, den sie auflösen.",
104	            sourceSignalRefs: signalRefs,
105	            relatedArtifactRefs: [{ type: "decision", id: decision.id }],
106	          }));
107	        }
108	
109	        // P-M01: Decision ohne Modell-Referenz (recommended) — nur wenn Durability gesetzt
110	        if (isNew && durability && (modelRefs.length === 0)) {
111	          obligations.push(makeObligation({
112	            rule: "P-M01",
113	            artifactId: decision.id,
114	            artifactTitle: decision.title,
115	            signalType: "decision",
116	            priority: "recommended",
117	            description: `Neue Entscheidung ohne Modell-Referenz: „${decision.title}"`,
118	            reason: "Decisions sollten auf relevante Modell-Abschnitte verweisen.",
119	            sourceSignalRefs: signalRefs,
120	            relatedArtifactRefs: [{ type: "decision", id: decision.id }],
121	          }));
122	        }
123	      }
124	    }
125	
126	    // --- Preference candidates ---
127	    if (candidate.candidateType === "preference") {
128	      const prefRef = candidate.artifactRefs?.find((r) => r.type === "preference");
129	      if (prefRef) {
130	        const pref = ctx.preferences.find((p) => p.id === prefRef.id);
131	        const stillActive = !pref || pref.status === "active";
132	        if (stillActive) {
133	          obligations.push(makeObligation({
134	            rule: "P-P01",
135	            artifactId: prefRef.id,
136	            artifactTitle: candidate.summary,
137	            signalType: "preference",
138	            priority: "important",
139	            description: `Aktive Präferenz noch nicht klassifiziert: ${candidate.summary}`,
140	            reason: "Aktive Präferenzen müssen weiter klassifiziert (→ Constraint, Trade-off) oder verworfen werden.",
141	            sourceSignalRefs: signalRefs,
142	            relatedArtifactRefs: [prefRef],
143	          }));
144	        }
145	      }
146	    }
147	
148	    // --- Task candidates (P-T01: critical) ---
149	    if (candidate.candidateType === "task") {
150	      const taskRef = candidate.artifactRefs?.find((r) => r.type === "task");
151	      const task = taskRef ? taskById.get(taskRef.id) : null;
152	      if (task && !(task.featureId ?? task.feature_id)) {
153	        obligations.push(makeObligation({
154	          rule: "P-T01",
155	          artifactId: task.id,
156	          artifactTitle: task.title,
157	          signalType: "task",
158	          priority: "critical",
159	          description: `Entwicklungsaufgabe ohne Feature-Referenz: „${task.title}"`,
160	          reason: "Featurebasierte Arbeit muss auf das Feature referenzieren, sonst geht die Zuordnung verloren.",
161	          sourceSignalRefs: signalRefs,
162	          relatedArtifactRefs: [{ type: "task", id: task.id }],
163	        }));
164	      }
165	    }
166	
167	    // --- Milestone candidates (P-MS01: important) ---
168	    // Collected per-candidate, aggregated after the loop (see below)
169	    if (candidate.candidateType === "milestone_candidate") {
170	      const msRef = candidate.artifactRefs?.find((r) => r.type === "milestone");
171	      const milestone = msRef ? milestoneById.get(msRef.id) : null;
172	      if (milestone) {
173	        const linkedFeatures = milestone.milestoneFeatures ?? milestone.milestone_features ?? [];
174	        if (linkedFeatures.length === 0 && milestone.status !== "completed" && milestone.status !== "cancelled") {
175	          ms01Hits.push({ milestone, signalRefs, ref: { type: "milestone", id: milestone.id } });
176	        }
177	      }
178	    }
179	
180	    // --- Finding candidates (P-B01: critical) ---
181	    if (candidate.candidateType === "finding") {
182	      // A finding signal was raised but may not be persisted yet
183	      obligations.push(makeObligation({
184	        rule: "P-B01",
185	        artifactId: candidate.artifactRefs?.[0]?.id,
186	        artifactTitle: candidate.summary,
187	        signalType: "finding",
188	        priority: "critical",
189	        description: `Konzeptrelevanter Befund erkannt: ${candidate.summary}`,
190	        reason: "Zentrale konzeptrelevante Befunde müssen als Issue/Befund gesichert werden.",
191	        sourceSignalRefs: signalRefs,
192	        relatedArtifactRefs: candidate.artifactRefs ?? [],
193	      }));
194	    }
195	
196	    // --- P-F11: Weiterentwicklung eines Features → Iteration öffnen (recommended) ---
197	    if (candidate.candidateType === "feature_iterate") {
198	      const featureRef = candidate.artifactRefs?.find((r) => r.type === "feature");
199	      const hint = featureRef
200	        ? `orcha feature iterate ${featureRef.id} --with-decision "…"`
201	        : `orcha feature iterate <id> --with-decision "…"`;
202	      obligations.push(makeObligation({
203	        rule: "P-F11",
204	        artifactId: featureRef?.id ?? candidate.id,
205	        artifactTitle: candidate.summary,
206	        signalType: "feature",
207	        priority: "recommended",
208	        description: `Weiterentwicklung erkannt — Iteration öffnen: ${candidate.summary}`,
209	        reason: `P-F10: Weiterentwicklung eines bestehenden Features erfolgt als neue Iteration, nicht als Subfeature. Vorschlag: ${hint}`,
210	        sourceSignalRefs: signalRefs,
211	        relatedArtifactRefs: featureRef ? [featureRef] : [],
212	      }));
213	    }
214	
215	    // --- Recommend semantic/procedural (P-G02: recommended) ---
216	    if (candidate.candidateType === "recommend_semantic" || candidate.candidateType === "recommend_procedural") {
217	      const memType = candidate.candidateType === "recommend_semantic" ? "semantisches" : "prozedurales";
218	      obligations.push(makeObligation({
219	        rule: "P-G02",
220	        artifactId: candidate.id,
221	        artifactTitle: candidate.summary,
222	        signalType: "memory",
223	        priority: "recommended",
224	        description: `Empfehlung für ${memType} Gedächtnis: ${candidate.summary}`,
225	        reason: `Sync empfiehlt ${memType} Gedächtnis, schreibt es aber nicht automatisch.`,
226	        sourceSignalRefs: signalRefs,
227	        relatedArtifactRefs: [],
228	      }));
229	    }
230	  }
231	
232	  // --- P-MS01: aggregate milestone obligations ---
233	  const MS01_AGGREGATE_THRESHOLD = 3;
234	  if (ms01Hits.length > MS01_AGGREGATE_THRESHOLD) {
235	    // Systemic gap — aggregate into single obligation
236	    const allSignalRefs = ms01Hits.flatMap((h) => h.signalRefs);
237	    const allArtifactRefs = ms01Hits.map((h) => h.ref);
238	    const names = ms01Hits.map((h) => h.milestone.name).slice(0, 3).join(", ");
239	    obligations.push(makeObligation({
240	      rule: "P-MS01",
241	      artifactId: "aggregate",
242	      artifactTitle: `${ms01Hits.length} Meilensteine`,
243	      signalType: "milestone",
244	      priority: "important",
245	      description: `${ms01Hits.length} Meilensteine ohne Feature-Bündelung (${names}, …)`,
246	      reason: "Mehrere Milestones ohne Feature-Bündelung — möglicherweise noch nicht gepflegt.",
247	      sourceSignalRefs: allSignalRefs,
248	      relatedArtifactRefs: allArtifactRefs,
249	    }));
250	  } else {
251	    // Few enough to be individually actionable
252	    for (const hit of ms01Hits) {
253	      obligations.push(makeObligation({
254	        rule: "P-MS01",
255	        artifactId: hit.milestone.id as string,
256	        artifactTitle: hit.milestone.name as string,
257	        signalType: "milestone",
258	        priority: "important",
259	        description: `Meilenstein ohne Feature-Bündelung: „${hit.milestone.name}"`,
260	        reason: "Meilensteine sollen Features bündeln, nicht Aufgaben.",
261	        sourceSignalRefs: hit.signalRefs,
262	        relatedArtifactRefs: [hit.ref],
263	      }));
264	    }
265	  }
266	
267	  // --- P-FL01: flow nodes without explicit actor (important) ---
268	  // Global check against all flow nodes, not candidate-based.
269	  // Policy verlangt: user/agent/system explizit gesetzt. Alle drei Werte sind gleichwertig.
270	  const flowNodesWithoutActor = ctx.flows.filter((n) => !n.actor);
271	  if (ctx.flows.length > 0 && flowNodesWithoutActor.length > 0) {
