380	
381	function truthy(v: unknown): boolean {
382	  if (v == null) return false;
383	  if (typeof v === "string") return v.trim().length > 0;
384	  if (Array.isArray(v)) return v.length > 0;
385	  return true;
386	}
387	
388	function isFieldFulfilled(
389	  key: string,
390	  f: Record<string, unknown>,
391	  ctx: SyncContext,
392	): boolean {
393	  const iter = (f.currentIteration as Record<string, unknown> | undefined) ?? {};
394	  switch (key) {
395	    case "name":
396	      return truthy(f.name);
397	    case "motivation":
398	      return truthy(f.motivation);
399	    case "description":
400	      return truthy(f.description);
401	    case "scope":
402	      return truthy(f.scope);
403	    case "non_goals":
404	      return truthy(f.nonGoals ?? f.non_goals);
405	    case "currentState":
406	      return truthy(f.currentState ?? f.current_state);
407	    case "acceptance_criteria":
408	      return truthy(f.acceptanceCriteria ?? iter.acceptanceCriteria ?? iter.acceptance_criteria);
409	    case "motivation_delta":
410	      return truthy(iter.motivationDelta ?? iter.motivation_delta);
411	    case "ak_or_subs": {
412	      const aks = f.acceptanceCriteria ?? iter.acceptanceCriteria ?? iter.acceptance_criteria;
413	      if (truthy(aks)) return true;
414	      // Has children?
415	      const fid = String(f.id);
416	      const hasChild = ctx.features.some((c) => String((c as Record<string, unknown>).parentFeatureId ?? (c as Record<string, unknown>).parent_feature_id ?? "") === fid);
417	      return hasChild;
418	    }
419	    case "open_questions_resolved": {
420	      // Erfüllt = keine offenen Findings (gap|ambiguity|contradiction) referenzieren dieses Feature.
421	      const fid = String(f.id);
422	      const blocking = new Set(["gap", "ambiguity", "contradiction"]);
423	      const hasOpenQuestion = ctx.findings.some((fin) => {
424	        const cat = String((fin as Record<string, unknown>).category ?? "");
425	        if (!blocking.has(cat)) return false;
426	        const status = String((fin as Record<string, unknown>).status ?? "");
427	        if (status !== "open") return false;
428	        const refs = ((fin as Record<string, unknown>).refs as Array<Record<string, unknown>> | undefined) ?? [];
429	        return refs.some((r) => String(r.artefaktType ?? r.artefakt_type ?? "") === "feature" && String(r.artefaktId ?? r.artefakt_id ?? "") === fid);
430	      });
431	      return !hasOpenQuestion;
432	    }
433	    case "epistemic_reviewed":
434	      return truthy(f.epistemicReviewedAt ?? iter.epistemicReviewedAt ?? iter.epistemic_reviewed_at);
435	    case "implementation_risks": {
436	      // Soft check: look at ctx.tasks for taskType=implementation_risk linked to this feature.
437	      const fid = String(f.id);
438	      const hasRisks = ctx.tasks.some((t) => {
439	        const tt = (t as Record<string, unknown>);
440	        return String(tt.featureId ?? tt.feature_id ?? "") === fid && (tt.taskType === "implementation_risk" || tt.task_type === "implementation_risk");
441	      });
442	      return hasRisks;
443	    }
444	    case "linked_decisions": {
445	      const fid = String(f.id);
446	      return ctx.decisions.some((d) => String((d as Record<string, unknown>).featureId ?? (d as Record<string, unknown>).feature_id ?? "") === fid);
447	    }
448	    case "linked_memory": {
449	      const fid = String(f.id);
450	      return ctx.memories.some((mem) => String((mem as Record<string, unknown>).sourceId ?? (mem as Record<string, unknown>).source_id ?? "") === fid);
451	    }
452	    case "external_references":
453	      return truthy(f.externalReferences ?? f.external_references);
454	    case "acceptance_met":
455	    case "deps_resolved_or_waived":
456	    case "impl_risks_resolved":
457	    case "no_stale_edges":
458	    case "deploy_green":
459	      // These are done-state checks. Currently uncomputable from sync context;
460	      // trust API-side guard at status transition.
461	      return true;
462	    default:
463	      return true;
464	  }
465	}
