22	/**
23	 * Returns the parts from the latest step of a message (after the last step-start marker).
24	 * If no step-start marker exists, returns all parts.
25	 */
26	export function getLatestStepParts(parts: MastraDBMessage['content']['parts']): MastraDBMessage['content']['parts'] {
27	  for (let i = parts.length - 1; i >= 0; i--) {
28	    if (parts[i]?.type === 'step-start') {
29	      return parts.slice(i + 1);
30	    }
31	  }
32	  return parts;
33	}
