35	/**
36	 * Returns true when a message contains at least one part with visible user/assistant
37	 * content (text, tool-invocation, reasoning, image, file).  Messages that only carry
38	 * internal `data-*` parts (buffering markers, observation markers, etc.) return false.
39	 */
40	function messageHasVisibleContent(msg: MastraDBMessage): boolean {
41	  const content = msg.content as { parts?: Array<{ type?: string }>; content?: string };
42	  if (content?.parts && Array.isArray(content.parts)) {
43	    return content.parts.some(p => {
44	      const t = p?.type;
45	      return t && !t.startsWith('data-') && t !== 'step-start';
46	    });
47	  }
48	  if (content?.content) return true;
49	  return false;
50	}
