52	/**
53	 * Build a messageRange string from the first and last messages that have visible
54	 * content.  Falls back to the full array boundaries when every message is data-only.
55	 */
56	export function buildMessageRange(messages: MastraDBMessage[]): string {
57	  const first = messages.find(messageHasVisibleContent) ?? messages[0]!;
58	  const last = [...messages].reverse().find(messageHasVisibleContent) ?? messages[messages.length - 1]!;
59	  return `${first.id}:${last.id}`;
60	}
