62	/**
63	 * Returns the unix-ms timestamp of the last non-data part in the last assistant
64	 * message, representing when the last visible LLM response completed. Used as the
65	 * last activity time for activateAfterIdle checks.
66	 */
67	export function getLastActivityFromMessages(messages?: MastraDBMessage[]): number | undefined {
68	  if (!messages) return undefined;
69	
70	  for (let i = messages.length - 1; i >= 0; i--) {
71	    const message = messages[i];
72	    if (!message || message.role !== 'assistant') {
73	      continue;
74	    }
75	
76	    if (!message.content || typeof message.content === 'string') {
77	      return message.createdAt ? new Date(message.createdAt).getTime() : undefined;
78	    }
79	
80	    for (let j = message.content.parts.length - 1; j >= 0; j--) {
81	      const part = message.content.parts[j];
82	      if (!part || part.type?.startsWith('data-')) {
83	        continue;
84	      }
85	
86	      if (part.createdAt !== undefined) {
87	        return part.createdAt;
88	      }
89	    }
90	
91	    return message.createdAt ? new Date(message.createdAt).getTime() : undefined;
92	  }
93	
94	  return undefined;
95	}
