851	function encodeAttachmentBase64(asset: unknown): string | undefined {
852	  if (typeof asset === 'string') {
853	    if (asset.startsWith('data:')) {
854	      const commaIndex = asset.indexOf(',');
855	      return commaIndex === -1 ? undefined : asset.slice(commaIndex + 1);
856	    }
857	
858	    if (/^https?:\/\//i.test(asset)) {
859	      return undefined;
860	    }
861	
862	    return asset;
863	  }
864	
865	  if (typeof Buffer !== 'undefined' && Buffer.isBuffer(asset)) {
866	    return asset.toString('base64');
867	  }
868	
869	  if (asset instanceof Uint8Array) {
870	    return Buffer.from(asset).toString('base64');
871	  }
872	
873	  if (asset instanceof ArrayBuffer) {
874	    return Buffer.from(asset).toString('base64');
875	  }
876	
877	  if (ArrayBuffer.isView(asset)) {
878	    return Buffer.from(asset.buffer, asset.byteOffset, asset.byteLength).toString('base64');
879	  }
880	
881	  return undefined;
882	}
