1357	      if (existingRequest) {
1358	        const remoteTokens = await existingRequest;
1359	        if (typeof remoteTokens === 'number' && Number.isFinite(remoteTokens) && remoteTokens > 0) {
1360	          setPartCacheEntry(part, remoteKey, {
1361	            v: TOKEN_ESTIMATE_CACHE_VERSION,
1362	            source: this.cacheSource,
1363	            key: remoteKey,
1364	            tokens: remoteTokens,
