1371	
1372	        let remoteTokens: number | undefined;
1373	        try {
1374	          remoteTokens = await remoteRequest;
1375	        } finally {
1376	          this.inFlightAttachmentCounts.delete(remoteKey);
1377	        }
1378	
1379	        if (typeof remoteTokens === 'number' && Number.isFinite(remoteTokens) && remoteTokens > 0) {
1380	          setPartCacheEntry(part, remoteKey, {
1381	            v: TOKEN_ESTIMATE_CACHE_VERSION,
1382	            source: this.cacheSource,
1383	            key: remoteKey,
1384	            tokens: remoteTokens,
1385	          });
