5	/**
6	 * Get the maximum value from a threshold (simple number or range).
7	 */
8	export function getMaxThreshold(threshold: number | ThresholdRange): number {
9	  if (typeof threshold === 'number') {
10	    return threshold;
11	  }
12	  return threshold.max;
13	}
14	
15	/**
16	 * Calculate dynamic threshold based on observation space.
17	 * When shareTokenBudget is enabled, the message threshold can expand
18	 * into unused observation space, up to the total context budget.
19	 *
20	 * Total budget = messageTokens + observationTokens
21	 * Effective threshold = totalBudget - currentObservationTokens
22	 *
23	 * Example with 30k:40k thresholds (70k total):
24	 * - 0 observations → messages can use ~70k
25	 * - 10k observations → messages can use ~60k
26	 * - 40k observations → messages back to ~30k
27	 */
28	export function calculateDynamicThreshold(
29	  threshold: number | ThresholdRange,
30	  currentObservationTokens: number,
31	): number {
32	  // If not using adaptive threshold (simple number), return as-is
33	  if (typeof threshold === 'number') {
34	    return threshold;
35	  }
36	
37	  // Adaptive threshold: use remaining space in total budget
38	  // Total budget is stored as threshold.max (base + reflection threshold)
39	  // Base threshold is stored as threshold.min
40	  const totalBudget = threshold.max;
41	  const baseThreshold = threshold.min;
42	
43	  // Effective threshold = total budget minus current observations
44	  // But never go below the base threshold
45	  const effectiveThreshold = Math.max(totalBudget - currentObservationTokens, baseThreshold);
46	
47	  return Math.round(effectiveThreshold);
48	}
49	
50	/**
51	 * Resolve bufferTokens config value.
52	 * Values in (0, 1) are treated as ratios of the message threshold.
53	 * e.g. bufferTokens: 0.25 with messageTokens: 20_000 → 5_000
54	 */
55	export function resolveBufferTokens(
56	  bufferTokens: number | false | undefined,
57	  messageTokens: number | ThresholdRange,
58	): number | undefined {
59	  if (bufferTokens === false) return undefined;
60	  if (bufferTokens === undefined) return undefined;
61	  if (bufferTokens > 0 && bufferTokens < 1) {
62	    return Math.round(getMaxThreshold(messageTokens) * bufferTokens);
63	  }
64	  return bufferTokens;
65	}
66	
67	/**
68	 * Resolve blockAfter config value.
69	 * Values in [1, 100) are treated as multipliers of the threshold.
70	 * e.g. blockAfter: 1.5 with messageTokens: 20_000 → 30_000
71	 * Values >= 100 are treated as absolute token counts.
72	 * Defaults to 1.2 (120% of threshold) when async buffering is enabled but blockAfter is omitted.
73	 */
74	export function resolveBlockAfter(
75	  blockAfter: number | undefined,
76	  messageTokens: number | ThresholdRange,
77	): number | undefined {
78	  if (blockAfter === undefined) return undefined;
79	  // Values between 1 (inclusive) and 100 (exclusive) are treated as multipliers of the threshold.
80	  // e.g. blockAfter: 1.5 means 1.5x the threshold. blockAfter: 1 means exactly at threshold.
81	  // Values >= 100 are treated as absolute token counts.
82	  if (blockAfter >= 1 && blockAfter < 100) {
83	    return Math.round(getMaxThreshold(messageTokens) * blockAfter);
84	  }
85	  return blockAfter;
86	}
87	
88	/**
89	 * Convert bufferActivation to an absolute retention floor (tokens to keep after activation).
90	 * When bufferActivation >= 1000, it's an absolute retention target.
91	 * Otherwise it's a ratio: retentionFloor = threshold * (1 - ratio).
92	 */
93	export function resolveRetentionFloor(bufferActivation: number, messageTokensThreshold: number): number {
94	  if (bufferActivation >= 1000) return bufferActivation;
95	  const ratio = Math.max(0, Math.min(1, bufferActivation));
96	  return messageTokensThreshold * (1 - ratio);
97	}
98	
99	/**
100	 * Convert bufferActivation to the equivalent ratio (0-1) for the storage layer.
101	 * When bufferActivation >= 1000, it's an absolute retention target, so we compute
102	 * the equivalent ratio: 1 - (bufferActivation / threshold).
103	 */
104	export function resolveActivationRatio(bufferActivation: number, messageTokensThreshold: number): number {
105	  if (bufferActivation >= 1000) {
106	    return Math.max(0, Math.min(1, 1 - bufferActivation / messageTokensThreshold));
107	  }
108	  return Math.max(0, Math.min(1, bufferActivation));
109	}
110	
111	/**
112	 * Calculate the projected message tokens that would be removed if activation happened now.
113	 * This replicates the chunk boundary logic in swapBufferedToActive without actually activating.
114	 */
115	export function calculateProjectedMessageRemoval(
116	  chunks: BufferedObservationChunk[],
117	  bufferActivation: number,
118	  messageTokensThreshold: number,
119	  currentPendingTokens: number,
120	): number {
121	  if (chunks.length === 0) return 0;
122	
123	  const retentionFloor = resolveRetentionFloor(bufferActivation, messageTokensThreshold);
124	  const targetMessageTokens = Math.max(0, currentPendingTokens - retentionFloor);
125	
126	  // Already within retention floor — no removal needed
127	  if (targetMessageTokens === 0) return 0;
128	
129	  // Find the closest chunk boundary to the target, biased over (prefer removing
130	  // slightly more than the target so remaining context lands at or below retentionFloor).
131	  // Track both best-over and best-under boundaries so we can fall back to under
132	  // if the over boundary would overshoot by too much.
133	  let cumulativeMessageTokens = 0;
134	  let bestOverBoundary = 0;
135	  let bestOverTokens = 0;
136	  let bestUnderBoundary = 0;
137	  let bestUnderTokens = 0;
138	
139	  for (let i = 0; i < chunks.length; i++) {
140	    cumulativeMessageTokens += chunks[i]!.messageTokens ?? 0;
141	    const boundary = i + 1;
142	
143	    if (cumulativeMessageTokens >= targetMessageTokens) {
144	      // Over or equal — track the closest (lowest) over boundary
145	      if (bestOverBoundary === 0 || cumulativeMessageTokens < bestOverTokens) {
146	        bestOverBoundary = boundary;
147	        bestOverTokens = cumulativeMessageTokens;
148	      }
149	    } else {
150	      // Under — track the closest (highest) under boundary
151	      if (cumulativeMessageTokens > bestUnderTokens) {
152	        bestUnderBoundary = boundary;
153	        bestUnderTokens = cumulativeMessageTokens;
154	      }
155	    }
156	  }
157	
158	  // Safeguard: if the over boundary would eat into more than 95% of the
159	  // retention floor, fall back to the best under boundary instead.
160	  // This prevents edge cases where a large chunk overshoots dramatically.
161	  // Additionally, never bias over if it would leave fewer than the smaller of
162	  // 1000 tokens or the retention floor — at that level the agent may lose
163	  // all meaningful context.
164	  const maxOvershoot = retentionFloor * 0.95;
165	  const overshoot = bestOverTokens - targetMessageTokens;
166	  const remainingAfterOver = currentPendingTokens - bestOverTokens;
167	  const remainingAfterUnder = currentPendingTokens - bestUnderTokens;
168	  // When activationRatio ≈ 1.0, retentionFloor is 0 and minRemaining becomes 0 — intentional for "activate everything" configs.
169	  const minRemaining = Math.min(1000, retentionFloor);
170	
171	  let bestBoundaryMessageTokens: number;
172	
173	  if (bestOverBoundary > 0 && overshoot <= maxOvershoot && remainingAfterOver >= minRemaining) {
174	    bestBoundaryMessageTokens = bestOverTokens;
175	  } else if (bestUnderBoundary > 0 && remainingAfterUnder >= minRemaining) {
176	    bestBoundaryMessageTokens = bestUnderTokens;
177	  } else if (bestOverBoundary > 0) {
178	    // All boundaries are over and exceed the safeguard — still activate
179	    // the closest over boundary (better than nothing)
180	    bestBoundaryMessageTokens = bestOverTokens;
181	  } else {
182	    return chunks[0]?.messageTokens ?? 0;
183	  }
184	
185	  return bestBoundaryMessageTokens;
186	}
