10	interface ReflectionObservationGroupSection {
11	  heading: string;
12	  body: string;
13	}
14	
15	const OBSERVATION_GROUP_PATTERN = /<observation-group\s([^>]*)>([\s\S]*?)<\/observation-group>/g;
16	const ATTRIBUTE_PATTERN = /([\w][\w-]*)="([^"]*)"/g;
17	const REFLECTION_GROUP_SPLIT_PATTERN = /^##\s+Group\s+/m;
18	
19	function parseObservationGroupAttributes(attributeString: string): Record<string, string> {
20	  const attributes: Record<string, string> = {};
21	
22	  for (const match of attributeString.matchAll(ATTRIBUTE_PATTERN)) {
23	    const [, key, value] = match;
24	    if (key && value !== undefined) {
25	      attributes[key] = value;
26	    }
27	  }
28	
29	  return attributes;
30	}
31	
32	function parseReflectionObservationGroupSections(content: string): ReflectionObservationGroupSection[] {
33	  const normalizedContent = content.trim();
34	  if (!normalizedContent || !REFLECTION_GROUP_SPLIT_PATTERN.test(normalizedContent)) {
35	    return [];
36	  }
37	
38	  return normalizedContent
39	    .split(REFLECTION_GROUP_SPLIT_PATTERN)
40	    .map(section => section.trim())
41	    .filter(Boolean)
42	    .map(section => {
43	      const newlineIndex = section.indexOf('\n');
44	      const heading = (newlineIndex >= 0 ? section.slice(0, newlineIndex) : section).trim();
45	      const body = (newlineIndex >= 0 ? section.slice(newlineIndex + 1) : '').trim();
46	
47	      return {
48	        heading,
49	        body: stripReflectionGroupMetadata(body),
50	      };
51	    });
52	}
53	
54	function stripReflectionGroupMetadata(body: string): string {
55	  return body.replace(/^_range:\s*`[^`]*`_\s*\n?/m, '').trim();
56	}
57	
58	export function generateAnchorId(): string {
59	  return randomBytes(8).toString('hex');
60	}
61	
62	export function wrapInObservationGroup(
63	  observations: string,
64	  range: string,
65	  id = generateAnchorId(),
66	  _sourceGroupIds?: string[],
67	  kind?: string,
68	): string {
69	  const content = observations.trim();
70	  const kindAttr = kind ? ` kind="${kind}"` : '';
71	  return `<observation-group id="${id}" range="${range}"${kindAttr}>\n${content}\n</observation-group>`;
72	}
73	
74	export function parseObservationGroups(observations: string): ObservationGroup[] {
75	  if (!observations) {
76	    return [];
77	  }
78	
79	  const groups: ObservationGroup[] = [];
80	  let match: RegExpExecArray | null;
81	
82	  while ((match = OBSERVATION_GROUP_PATTERN.exec(observations)) !== null) {
83	    const attributes = parseObservationGroupAttributes(match[1] ?? '');
84	    const id = attributes.id;
85	    const range = attributes.range;
86	
87	    if (!id || !range) {
88	      continue;
89	    }
90	
91	    groups.push({
92	      id,
93	      range,
94	      kind: attributes.kind,
95	      content: match[2]!.trim(),
96	    });
97	  }
98	
99	  return groups;
100	}

